<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$period=$_GET['period']??'month';$fmt=$period==='day'?'%Y-%m-%d':'%Y-%m';$s=db()->prepare("SELECT DATE_FORMAT(sold_at,'$fmt') label,COUNT(*) sales,COALESCE(SUM(profit),0) profit,COALESCE(SUM(selling_price),0) revenue FROM sales WHERE seller_id=? AND id NOT IN(SELECT sale_id FROM returns) GROUP BY label ORDER BY label DESC LIMIT 31");$s->execute([$u['id']]);$d=db()->prepare('SELECT s.*,p.name,p.brand,p.category,p.unique_identifier,p.identifier_type FROM sales s JOIN products p ON p.id=s.product_id WHERE s.seller_id=? AND s.id NOT IN(SELECT sale_id FROM returns) ORDER BY s.sold_at DESC');$d->execute([$u['id']]);out(['success'=>true,'report'=>$s->fetchAll(),'sold_products'=>$d->fetchAll()]);
